/**
 * Oracle Core Types — Sovereign autonomous arbitration & Bayesian aggregation
 */

export interface Claim {
  stance: "yes" | "no" | "uncertain";
  llr?: number; // log-likelihood ratio bounded <= 2.0
  cluster_id?: string;
  urls?: string[];
  summary?: string;
}

export interface JudgeAttempt {
  attempt_no: number;
  slot_alias: string;
  provider_requested?: string | null;
  latency_s: number;
  http_status?: number | null;
  correlation_id?: string | null;
  response_excerpt?: string | null;
  failure_category?: string;
  error?: string | null;
  timestamp: string;
}

export interface JudgePosterior {
  judge_id: string;
  posterior: number;
  confidence: number;
  cal_weight: number;
  reliability: number;
  provider: string;
  model_family?: string;
  valid: boolean;
  refused: boolean;
  claims: Claim[];
  reasoning_summary?: string;
  reasoning_content?: string;
  attempts: JudgeAttempt[];
}

export interface ContribEntry {
  judge: string;
  provider: string;
  model_family?: string;
  weight_raw: number;
  provider_share: number;
  weight: number;
  posterior: number;
  logit_contrib: number;
}

export interface DisagreementFeatures {
  confidence: number;
  spread: number;
  evidence_overlap: number;
  stance_divergence: number;
  n_judges: number;
  n_providers: number;
  providers: string[];
  provider_concentration: number;
  note?: string;
}

export interface ConfidenceInterval {
  lower: number;
  upper: number;
  method: string;
  alpha: number;
}

export interface Verdict {
  verdict_id: string;
  question: string;
  tier: "AUTO" | "VOTE" | "DEBATE" | "HUMAN";
  probability: number;
  prior: number;
  confidence: number;
  confidence_interval: ConfidenceInterval;
  disagreement: DisagreementFeatures;
  contributions: ContribEntry[];
  judges_consulted: number;
  judges_valid: number;
  timestamp: string;
  latency_s: number;
  models: string[];
  limitations: string[];
  settled: boolean;
  error?: string;
}

export interface FramingResult {
  question: string;
  prior: number;
  resolution_criteria: string;
  fail_closed: boolean;
  category?: string;
}

/**
 * Bayesian mathematics and statistical bounds for Oracle Core.
 */

export const PROB_FLOOR = 0.001;
export const PROB_CEIL = 0.999;

export function clampProb(p: number): number {
  if (Number.isNaN(p)) return 0.5;
  return Math.min(PROB_CEIL, Math.max(PROB_FLOOR, p));
}

export function logit(p: number): number {
  const c = clampProb(p);
  return Math.log(c / (1.0 - c));
}

export function invLogit(x: number): number {
  if (Number.isNaN(x)) return 0.5;
  if (x > 35) return PROB_CEIL;
  if (x < -35) return PROB_FLOOR;
  const p = 1.0 / (1.0 + Math.exp(-x));
  return clampProb(p);
}

/**
 * Wilson score interval for binomial proportions.
 */
export function wilsonScoreInterval(successes: number, total: number, alpha = 0.05): { lower: number; upper: number } {
  if (total <= 0) return { lower: 0, upper: 1 };
  // z for two-tailed alpha=0.05 is ~1.96
  const z = 1.959963984540054;
  const p = successes / total;
  const z2 = z * z;
  const n = total;

  const denominator = 1 + z2 / n;
  const center = p + z2 / (2 * n);
  const spread = z * Math.sqrt((p * (1 - p) + z2 / (4 * n)) / n);

  const lower = Math.max(0, (center - spread) / denominator);
  const upper = Math.min(1, (center + spread) / denominator);

  return { lower, upper };
}

/**
 * Clopper-Pearson exact confidence interval approximation.
 */
export function clopperPearsonInterval(successes: number, total: number, alpha = 0.05): { lower: number; upper: number } {
  if (total <= 0) return { lower: 0, upper: 1 };
  const k = successes;
  const n = total;

  if (k === 0) {
    const upper = 1 - Math.pow(alpha / 2, 1 / n);
    return { lower: 0, upper: Math.min(1, upper) };
  }
  if (k === n) {
    const lower = Math.pow(alpha / 2, 1 / n);
    return { lower: Math.max(0, lower), upper: 1 };
  }

  // Refined Wilson approximation with continuity correction as standard high-precision Clopper-Pearson proxy
  const z = 1.959963984540054;
  const p = k / n;
  const z2 = z * z;
  const lower = Math.max(0, (2 * k + z2 - 1 - z * Math.sqrt(z2 - (2 + 1 / n) + 4 * p * (n * (1 - p) + 1))) / (2 * (n + z2)));
  const upper = Math.min(1, (2 * k + z2 + 1 + z * Math.sqrt(z2 + (2 - 1 / n) + 4 * p * (n * (1 - p) - 1))) / (2 * (n + z2)));

  return { lower: Math.max(0, lower), upper: Math.min(1, upper) };
}

/**
 * Deterministic aggregation engine — the Oracle's constitutional core.
 * Owns every number: verdicts, probabilities, confidence intervals, escalation.
 */

import { clampProb, logit, invLogit, clopperPearsonInterval, wilsonScoreInterval } from "./bayes.ts";
import type { JudgePosterior, ContribEntry, DisagreementFeatures, Verdict, ConfidenceInterval } from "./types.ts";

export const GATE_ALPHA = 0.05;
export const GATE_MIN_ACCURACY = 0.80;
export const AUTO_P_HIGH = 0.85;
export const AUTO_P_LOW = 0.15;

export function pooledPosterior(
  prior: number,
  judges: JudgePosterior[],
  providerCollapse = true
): { probability: number; contributions: ContribEntry[] } {
  const live = judges.filter((j) => j.valid && !j.refused);
  if (live.length === 0) {
    return { probability: clampProb(prior), contributions: [] };
  }

  // Calculate infrastructure provider mass
  const provMass = new Map<string, number>();
  for (const j of live) {
    const p = j.provider || "unknown";
    const rawW = j.cal_weight * j.reliability;
    provMass.set(p, (provMass.get(p) ?? 0) + rawW);
  }

  let lo = logit(prior);
  const contributions: ContribEntry[] = [];

  for (const j of live) {
    const prov = j.provider || "unknown";
    const rawW = j.cal_weight * j.reliability;
    const totalMass = provMass.get(prov) ?? 1.0;
    const share = totalMass > 0 ? rawW / totalMass : 0.0;
    const w = providerCollapse ? share : rawW;
    const c = w * logit(j.posterior);
    lo += c;

    contributions.push({
      judge: j.judge_id,
      provider: prov,
      model_family: j.model_family,
      weight_raw: rawW,
      provider_share: share,
      weight: w,
      posterior: j.posterior,
      logit_contrib: c,
    });
  }

  const post = invLogit(lo);
  return { probability: post, contributions };
}

export function disagreementFeatures(judges: JudgePosterior[]): DisagreementFeatures {
  const live = judges.filter((j) => j.valid && !j.refused);
  if (live.length < 2) {
    const provs = live.map((j) => j.provider || "unknown");
    return {
      confidence: 0.5,
      spread: 0.0,
      evidence_overlap: 0.0,
      stance_divergence: 0.0,
      n_judges: live.length,
      n_providers: new Set(provs).size,
      providers: Array.from(new Set(provs)),
      provider_concentration: 0.0,
      note: "single judge or fewer — no structure",
    };
  }

  const posts = live.map((j) => j.posterior);
  const mean = posts.reduce((a, b) => a + b, 0) / posts.length;
  const spread = Math.sqrt(posts.reduce((acc, p) => acc + Math.pow(p - mean, 2), 0) / posts.length);

  // Evidence overlap (Jaccard similarity across claim clusters)
  const sets = live.map((j) => new Set(j.claims.map((c) => c.cluster_id).filter(Boolean) as string[]));
  const pairwise: number[] = [];
  for (let a = 0; a < sets.length; a++) {
    for (let b = a + 1; b < sets.length; b++) {
      const union = new Set([...sets[a], ...sets[b]]);
      if (union.size === 0) {
        pairwise.push(1.0);
        continue;
      }
      let intersectionCount = 0;
      for (const item of sets[a]) {
        if (sets[b].has(item)) intersectionCount++;
      }
      pairwise.push(intersectionCount / union.size);
    }
  }
  const overlap = pairwise.length > 0 ? pairwise.reduce((a, b) => a + b, 0) / pairwise.length : 1.0;

  // Stance divergence (minority fraction around 0.5)
  const yes = posts.filter((p) => p >= 0.5).length;
  const divergence = Math.min(yes, posts.length - yes) / posts.length;

  const provs = Array.from(new Set(live.map((j) => j.provider || "unknown")));
  const nProviders = provs.length;
  const concentration = 1.0 - nProviders / live.length;

  // Structural confidence from DiscoUQ-lite
  const independence = 1.0 - overlap;
  const agreement = 1.0 - Math.min(1.0, spread * 4.0);
  const base = Math.min(1.0, Math.max(0.0, 0.5 * agreement + 0.3 * independence + 0.2 * (1.0 - divergence * 2.0)));
  const diversityFactor = 0.5 + 0.5 * (nProviders / live.length);
  const confidence = base * diversityFactor;

  return {
    confidence,
    spread,
    evidence_overlap: overlap,
    stance_divergence: divergence,
    n_judges: live.length,
    n_providers: nProviders,
    providers: provs,
    provider_concentration: concentration,
  };
}

export function determineTier(
  probability: number,
  confidence: number,
  disagreement: DisagreementFeatures,
  allowDebate = true
): "AUTO" | "VOTE" | "DEBATE" | "HUMAN" {
  if (disagreement.n_judges === 0) return "HUMAN";

  // Auto criteria: strong conviction, high structural confidence, minimal spread
  if ((probability >= AUTO_P_HIGH || probability <= AUTO_P_LOW) && confidence >= 0.75 && disagreement.spread < 0.15) {
    return "AUTO";
  }

  // If severe disagreement or provider herding on single provider
  if (disagreement.stance_divergence > 0.35 || disagreement.spread > 0.30) {
    return allowDebate ? "DEBATE" : "VOTE";
  }

  // Moderate consensus
  if (confidence >= 0.60 && (probability >= 0.70 || probability <= 0.30)) {
    return "VOTE";
  }

  return allowDebate ? "DEBATE" : "HUMAN";
}

