/**
 * Herd Transport — native Bun fetch client for Sovereign model gateway.
 * Supports structured outputs (response_format), reasoning tokens, and fail-closed timeout.
 */

import type { JudgeAttempt } from "./types.ts";

export const DEFAULT_HERD_URL = process.env.HERD_URL ?? "http://127.0.0.1:25100";

export interface ChatResponse {
  ok: boolean;
  text: string | null;
  reasoning_content?: string | null;
  latency_s: number;
  usage: Record<string, unknown>;
  http_status: number | null;
  model_served: string | null;
  provider_served: string | null;
  refusal: string | null;
  server: string | null;
  error: string | null;
  error_kind: string | null;
  error_body: string | null;
}

export async function herdChat(
  model: string,
  prompt: string,
  options: {
    herdUrl?: string;
    timeoutMs?: number;
    maxTokens?: number;
    jsonMode?: boolean;
    temperature?: number;
  } = {}
): Promise<ChatResponse> {
  const herdUrl = (options.herdUrl ?? DEFAULT_HERD_URL).replace(/\/+$/, "");
  const timeoutMs = options.timeoutMs ?? 90_000;
  const maxTokens = options.maxTokens ?? 1500;
  const jsonMode = options.jsonMode ?? true;
  const temperature = options.temperature ?? 0.2;

  const buildBody = (withJsonFormat: boolean) => {
    const payload: Record<string, unknown> = {
      model,
      messages: [{ role: "user", content: prompt }],
      temperature,
      max_tokens: maxTokens,
    };
    if (withJsonFormat && jsonMode) {
      payload.response_format = { type: "json_object" };
    }
    return JSON.stringify(payload);
  };

  const t0 = performance.now();

  try {
    const res = await fetch(`${herdUrl}/v1/chat/completions`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: buildBody(jsonMode),
      signal: AbortSignal.timeout(timeoutMs),
    });

    const latency_s = (performance.now() - t0) / 1000;
    const serverHeader = res.headers.get("Server");

    if (!res.ok) {
      const errBody = (await res.text().catch(() => "")).slice(0, 500);

      // If 400 rejection on response_format, retry once without it
      if (res.status === 400 && jsonMode && (errBody.includes("response_format") || errBody.includes("schema"))) {
        const retryRes = await fetch(`${herdUrl}/v1/chat/completions`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: buildBody(false),
          signal: AbortSignal.timeout(timeoutMs),
        });
        if (retryRes.ok) {
          const retryData = (await retryRes.json()) as any;
          const msg = retryData.choices?.[0]?.message ?? {};
          return {
            ok: true,
            text: msg.content ?? null,
            reasoning_content: msg.reasoning_content ?? msg.thinking ?? null,
            latency_s: (performance.now() - t0) / 1000,
            usage: retryData.usage ?? {},
            http_status: retryRes.status,
            model_served: retryData.model ?? null,
            provider_served: retryData.provider ?? null,
            refusal: msg.refusal ?? null,
            server: retryRes.headers.get("Server"),
            error: null,
            error_kind: null,
            error_body: null,
          };
        }
      }

      return {
        ok: false,
        text: null,
        latency_s,
        usage: {},
        http_status: res.status,
        model_served: null,
        provider_served: null,
        refusal: null,
        server: serverHeader,
        error: `HTTPError ${res.status}: ${res.statusText}`,
        error_kind: res.status === 429 ? "http_429" : res.status >= 500 ? "http_5xx" : "http_4xx",
        error_body: errBody,
      };
    }

    const data = (await res.json()) as any;
    const msg = data.choices?.[0]?.message ?? {};

    return {
      ok: true,
      text: msg.content ?? null,
      reasoning_content: msg.reasoning_content ?? msg.thinking ?? null,
      latency_s,
      usage: data.usage ?? {},
      http_status: res.status,
      model_served: data.model ?? null,
      provider_served: data.provider ?? null,
      refusal: msg.refusal ?? null,
      server: serverHeader,
      error: null,
      error_kind: null,
      error_body: null,
    };
  } catch (err: any) {
    const latency_s = (performance.now() - t0) / 1000;
    const isTimeout = err?.name === "TimeoutError" || String(err).toLowerCase().includes("timeout");
    return {
      ok: false,
      text: null,
      latency_s,
      usage: {},
      http_status: null,
      model_served: null,
      provider_served: null,
      refusal: null,
      server: null,
      error: `${err?.name ?? "Error"}: ${err?.message ?? String(err)}`,
      error_kind: isTimeout ? "timeout" : "connection_error",
      error_body: null,
    };
  }
}

/**
 * Oracle Ask Engine — Multi-agent Bayesian Consensus Pipeline.
 */

import { randomUUID } from "node:crypto";
import { appendFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { herdChat } from "./transport.ts";
import { pooledPosterior, disagreementFeatures, determineTier } from "./engine.ts";
import { clopperPearsonInterval, clampProb } from "./bayes.ts";
import type { JudgePosterior, JudgeAttempt, Claim, Verdict } from "./types.ts";

export const DEFAULT_JUDGE_MODELS = [
  "beellama/exaone-4-0-1-2b-q4km",
  "beellama/exaone-4-0-1-2b-q6k",
  "beellama/exaone-4-0-1-2b-q80",
];

const REFUSAL_PATTERNS = [
  "i can't", "i cannot", "i'm unable", "i am unable",
  "unable to comply", "unable to answer", "against my",
  "refuse to", "decline to", "not able to",
];

export function extractJson(text: string | null): any {
  if (!text) return null;
  const start = text.indexOf("{");
  if (start < 0) return null;

  let depth = 0;
  let inStr = false;
  let esc = false;

  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inStr) {
      if (esc) {
        esc = false;
      } else if (ch === "\\") {
        esc = true;
      } else if (ch === '"') {
        inStr = false;
      }
    } else {
      if (ch === '"') {
        inStr = true;
      } else if (ch === "{") {
        depth++;
      } else if (ch === "}") {
        depth--;
        if (depth === 0) {
          try {
            return JSON.parse(text.slice(start, i + 1));
          } catch {
            return null;
          }
        }
      }
    }
  }
  return null;
}

export function buildJudgePrompt(question: string, evidenceItems: any[] = []): string {
  const evText = evidenceItems.length > 0
    ? `\nEvidence items:\n${evidenceItems.map((e, idx) => `[${idx + 1}] ${JSON.stringify(e)}`).join("\n")}\n`
    : "";

  return `You are an unbiased judicial oracle analyzing a verifiable empirical claim.
Your output must be strictly valid JSON matching this schema:
{
  "posterior": <float between 0.01 and 0.99 indicating probability that the claim is TRUE>,
  "confidence": <float between 0.0 and 1.0 indicating your certainty in this posterior>,
  "claims": [
    {
      "stance": "yes" | "no" | "uncertain",
      "cluster_id": "<concise cluster topic tag>",
      "summary": "<one sentence summarizing reasoning>"
    }
  ],
  "reasoning_summary": "<2-3 sentences explaining your posterior estimate>"
}

Claim to judge:
"${question}"
${evText}
Return ONLY valid JSON. No markdown fences. No extra text.`;
}

export async function judgeOnce(
  model: string,
  prompt: string,
  timeoutMs = 60_000
): Promise<{ posterior: JudgePosterior; attempt: JudgeAttempt }> {
  const t0 = performance.now();
  const res = await herdChat(model, prompt, { timeoutMs, jsonMode: true });
  const latency_s = (performance.now() - t0) / 1000;

  const text = res.text ?? "";
  const looksLikeRefusal = REFUSAL_PATTERNS.some((p) => text.toLowerCase().includes(p));

  const attempt: JudgeAttempt = {
    attempt_no: 1,
    slot_alias: model,
    provider_requested: res.provider_served ?? "herd-local",
    latency_s,
    http_status: res.http_status,
    correlation_id: randomUUID(),
    response_excerpt: text.slice(0, 300),
    failure_category: res.error_kind ?? (looksLikeRefusal ? "refusal" : "ok"),
    error: res.error,
    timestamp: new Date().toISOString(),
  };

  if (!res.ok || looksLikeRefusal) {
    return {
      posterior: {
        judge_id: model,
        posterior: 0.5,
        confidence: 0.0,
        cal_weight: 1.0,
        reliability: 0.0,
        provider: res.provider_served ?? "herd-local",
        valid: false,
        refused: looksLikeRefusal,
        claims: [],
        attempts: [attempt],
      },
      attempt,
    };
  }

  const parsed = extractJson(text);
  if (!parsed || typeof parsed.posterior !== "number") {
    attempt.failure_category = "parse_failure";
    return {
      posterior: {
        judge_id: model,
        posterior: 0.5,
        confidence: 0.0,
        cal_weight: 1.0,
        reliability: 0.0,
        provider: res.provider_served ?? "herd-local",
        valid: false,
        refused: false,
        claims: [],
        attempts: [attempt],
      },
      attempt,
    };
  }

  const post = clampProb(parsed.posterior);
  const conf = Math.min(1.0, Math.max(0.0, typeof parsed.confidence === "number" ? parsed.confidence : 0.7));
  const rawClaims = Array.isArray(parsed.claims) ? parsed.claims : [];
  const claims: Claim[] = rawClaims.map((c: any) => ({
    stance: c?.stance === "yes" || c?.stance === "no" ? c.stance : "uncertain",
    cluster_id: typeof c?.cluster_id === "string" ? c.cluster_id : undefined,
    summary: typeof c?.summary === "string" ? c.summary : undefined,
  }));

  return {
    posterior: {
      judge_id: model,
      posterior: post,
      confidence: conf,
      cal_weight: 1.0,
      reliability: 1.0,
      provider: res.provider_served ?? "herd-local",
      model_family: res.model_served ?? model,
      valid: true,
      refused: false,
      claims,
      reasoning_summary: parsed.reasoning_summary,
      reasoning_content: res.reasoning_content ?? undefined,
      attempts: [attempt],
    },
    attempt,
  };
}

export async function runAsk(
  question: string,
  options: {
    models?: string[];
    timeout_s?: number;
    evidence?: any[];
    allow_debate?: boolean;
    ledgerPath?: string;
  } = {}
): Promise<Verdict> {
  const t0 = performance.now();
  const models = options.models && options.models.length > 0 ? options.models : DEFAULT_JUDGE_MODELS;
  const timeoutMs = (options.timeout_s ?? 90) * 1000;
  const prompt = buildJudgePrompt(question, options.evidence);

  // Parallel judge evaluations
  const judgePromises = models.map((m) => judgeOnce(m, prompt, timeoutMs));
  const settled = await Promise.allSettled(judgePromises);

  const judges: JudgePosterior[] = [];
  for (const s of settled) {
    if (s.status === "fulfilled") {
      judges.push(s.value.posterior);
    }
  }

  const prior = 0.5;
  const { probability, contributions } = pooledPosterior(prior, judges);
  const disagreement = disagreementFeatures(judges);
  const tier = determineTier(probability, disagreement.confidence, disagreement, options.allow_debate ?? true);

  // Wilson & Clopper-Pearson confidence intervals based on positive judge counts
  const validLive = judges.filter((j) => j.valid && !j.refused);
  const positiveJudges = validLive.filter((j) => j.posterior >= 0.5).length;
  const ci = clopperPearsonInterval(positiveJudges, validLive.length || 1);

  const verdict: Verdict = {
    verdict_id: `vrd-${Date.now().toString(36)}-${randomUUID().slice(0, 6)}`,
    question,
    tier,
    probability,
    prior,
    confidence: disagreement.confidence,
    confidence_interval: {
      lower: ci.lower,
      upper: ci.upper,
      method: "clopper_pearson",
      alpha: 0.05,
    },
    disagreement,
    contributions,
    judges_consulted: models.length,
    judges_valid: validLive.length,
    timestamp: new Date().toISOString(),
    latency_s: (performance.now() - t0) / 1000,
    models,
    limitations: validLive.length < models.length ? [`${models.length - validLive.length} judges failed or timed out`] : [],
    settled: true,
  };

  // Persist to ledger if path configured
  const ledgerPath = options.ledgerPath ?? "/home/toxic/sovereign/agents/oracle-market/ledger/ledger.jsonl";
  try {
    await mkdir(dirname(ledgerPath), { recursive: true });
    await appendFile(ledgerPath, `${JSON.stringify(verdict)}\n`, "utf8");
  } catch {
    // Ledger write failures are non-fatal to the query
  }

  return verdict;
}

/**
 * oracld daemon — High-Performance Native Bun HTTP & SSE Streaming Server for Oracle Core.
 *
 * Supervised by pitchfork or run standalone via oracld.
 * Endpoints:
 *   GET  /health  -> JSON health & status
 *   GET  /live    -> Server-Sent Events (SSE) stream of live ledger entries & heartbeats
 *   GET  /stream  -> Alias for /live
 *   POST /ask     -> Bayesian oracle consultation (JSON or SSE stream)
 */

import { existsSync, statSync } from "node:fs";
import { open } from "node:fs/promises";
import { runAsk } from "./oracle.ts";
import type { Verdict } from "./types.ts";

const LISTEN_PORT = Number(process.env.ORACLE_CORE_PORT ?? 25151);
const LEDGER_PATH = process.env.ORACLE_LEDGER_PATH ?? "/home/toxic/sovereign/agents/oracle-market/ledger/ledger.jsonl";
const START_TIME = Date.now();
let verdictCounter = 0;

// Set of active SSE subscribers
const sseClients = new Set<(event: string, data: any) => void>();

export function broadcastEvent(event: string, data: any) {
  for (const client of sseClients) {
    try {
      client(event, data);
    } catch {
      sseClients.delete(client);
    }
  }
}

// Watch ledger file for live appended entries
async function startLedgerWatcher() {
  let lastSize = 0;
  if (existsSync(LEDGER_PATH)) {
    try {
      lastSize = statSync(LEDGER_PATH).size;
    } catch {}
  }

  // Periodic tail with non-blocking fd reading
  setInterval(async () => {
    if (!existsSync(LEDGER_PATH)) return;
    try {
      const currentSize = statSync(LEDGER_PATH).size;
      if (currentSize <= lastSize) {
        lastSize = currentSize;
        return;
      }

      const file = await open(LEDGER_PATH, "r");
      const buffer = Buffer.alloc(currentSize - lastSize);
      await file.read(buffer, 0, buffer.length, lastSize);
      await file.close();
      lastSize = currentSize;

      const lines = buffer.toString("utf8").split("\n").filter((l) => l.trim().length > 0);
      for (const line of lines) {
        try {
          const parsed = JSON.parse(line);
          broadcastEvent("ledger", parsed);
        } catch {
          broadcastEvent("raw_ledger", line);
        }
      }
    } catch (e) {
      // transient read errors are ignored
    }
  }, 1000);
}

export function startDaemon(port = LISTEN_PORT) {
  startLedgerWatcher();

  const server = Bun.serve({
    port,
    idleTimeout: 255, // Keep SSE alive
    async fetch(req) {
      const url = new URL(req.url);

      // CORS headers
      const corsHeaders = {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type, Authorization",
      };

      if (req.method === "OPTIONS") {
        return new Response(null, { status: 204, headers: corsHeaders });
      }

      // GET /health
      if (req.method === "GET" && url.pathname === "/health") {
        const uptime_s = (Date.now() - START_TIME) / 1000;
        return Response.json(
          {
            ok: true,
            runtime: "bun",
            bun_version: Bun.version,
            port,
            uptime_s,
            verdicts: verdictCounter,
            subscribers: sseClients.size,
            ledger_path: LEDGER_PATH,
          },
          { headers: corsHeaders }
        );
      }

      // GET /live or /stream (Server-Sent Events)
      if (req.method === "GET" && (url.pathname === "/live" || url.pathname === "/stream")) {
        let heartbeatTimer: any = null;
        let listener: any = null;

        const stream = new ReadableStream({
          start(controller) {
            listener = (event: string, data: any) => {
              const payload = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
              controller.enqueue(new TextEncoder().encode(payload));
            };
            sseClients.add(listener);

            // Initial connection event
            const welcome = `event: connected\ndata: ${JSON.stringify({
              runtime: "bun",
              time: new Date().toISOString(),
              subscribers: sseClients.size,
            })}\n\n`;
            controller.enqueue(new TextEncoder().encode(welcome));

            // Heartbeat every 10s
            heartbeatTimer = setInterval(() => {
              try {
                const hb = `event: heartbeat\ndata: ${JSON.stringify({
                  time: new Date().toISOString(),
                  uptime_s: (Date.now() - START_TIME) / 1000,
                  verdicts: verdictCounter,
                })}\n\n`;
                controller.enqueue(new TextEncoder().encode(hb));
              } catch {
                clearInterval(heartbeatTimer);
              }
            }, 10_000);
          },
          cancel() {
            if (listener) sseClients.delete(listener);
            if (heartbeatTimer) clearInterval(heartbeatTimer);
          },
        });

        return new Response(stream, {
          headers: {
            ...corsHeaders,
            "Content-Type": "text/event-stream; charset=utf-8",
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
          },
        });
      }

      // POST /ask
      if (req.method === "POST" && url.pathname === "/ask") {
        try {
          const body = (await req.json()) as any;
          const question = (body?.question ?? "").trim();
          if (!question) {
            return Response.json({ ok: false, error: "question required" }, { status: 400, headers: corsHeaders });
          }

          const wantsStream = body?.stream === true;
          broadcastEvent("ask_start", { question, stream: wantsStream });

          if (wantsStream) {
            // Stream deliberation steps via SSE
            const stream = new ReadableStream({
              async start(controller) {
                const send = (event: string, data: any) => {
                  controller.enqueue(new TextEncoder().encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`));
                };

                send("status", { step: "framing", question });
                try {
                  const verdict = await runAsk(question, {
                    models: body?.models,
                    timeout_s: body?.timeout_s,
                    evidence: body?.evidence,
                    allow_debate: body?.allow_debate,
                    ledgerPath: LEDGER_PATH,
                  });
                  verdictCounter++;
                  broadcastEvent("verdict", verdict);
                  send("verdict", verdict);
                  send("done", { ok: true });
                } catch (err: any) {
                  send("error", { message: err?.message ?? String(err) });
                } finally {
                  controller.close();
                }
              },
            });

            return new Response(stream, {
              headers: {
                ...corsHeaders,
                "Content-Type": "text/event-stream; charset=utf-8",
                "Cache-Control": "no-cache",
              },
            });
          }

          // Standard JSON response
          const verdict = await runAsk(question, {
            models: body?.models,
            timeout_s: body?.timeout_s,
            evidence: body?.evidence,
            allow_debate: body?.allow_debate,
            ledgerPath: LEDGER_PATH,
          });
          verdictCounter++;
          broadcastEvent("verdict", verdict);
          return Response.json(verdict, { headers: corsHeaders });
        } catch (err: any) {
          return Response.json(
            { ok: false, error: `${err?.name ?? "Error"}: ${err?.message ?? String(err)}` },
            { status: 500, headers: corsHeaders }
          );
        }
      }

      return Response.json({ ok: false, error: `unknown route ${req.method} ${url.pathname}` }, { status: 404, headers: corsHeaders });
    },
  });

  console.log(`[oracld] Native Bun daemon listening on http://127.0.0.1:${port} (pid ${process.pid})`);
  return server;
}

if (import.meta.main) {
  startDaemon();
}

#!/usr/bin/env bun
/**
 * oracld — Sovereign Oracle CLI & Live Streaming Client
 *
 * Usage:
 *   oracld health                  Check oracle daemon health
 *   oracld live                    Stream live events and ledger updates via SSE
 *   oracld ask "Will X happen?"     Consult the oracle with Bayesian consensus
 *   oracld serve [--port 25151]    Run native Bun oracle daemon
 */

import { startDaemon } from "./daemon.ts";
import { runAsk } from "./oracle.ts";

const ORACLE_URL = process.env.ORACLE_CORE_URL ?? "http://127.0.0.1:25151";

function printHelp() {
  console.log(`oracld — Sovereign Autonomous Oracle & Real-Time Decision Daemon (Bun native)

Usage:
  oracld health                  Check oracle health status
  oracld live                    Subscribe to live SSE event & ledger stream
  oracld ask "question"          Ask oracle claim for Bayesian consensus
  oracld serve [--port 25151]    Start the high-performance Bun oracle daemon
  oracld --help                  Show this help message
`);
}

async function handleHealth() {
  try {
    const res = await fetch(`${ORACLE_URL}/health`);
    if (!res.ok) {
      console.error(`[oracld] Health check failed with status ${res.status}`);
      process.exit(1);
    }
    const data = await res.json();
    console.log(JSON.stringify(data, null, 2));
  } catch (err: any) {
    console.error(`[oracld] Could not connect to oracle daemon at ${ORACLE_URL}: ${err.message}`);
    process.exit(1);
  }
}

async function handleLive() {
  console.log(`[oracld] Connecting to live event stream at ${ORACLE_URL}/live ...`);
  try {
    const res = await fetch(`${ORACLE_URL}/live`, {
      headers: { Accept: "text/event-stream" },
    });

    if (!res.ok || !res.body) {
      console.error(`[oracld] Failed to connect to stream: ${res.status} ${res.statusText}`);
      process.exit(1);
    }

    console.log(`[oracld] Connected. Streaming live events (Ctrl+C to stop):\n`);
    const reader = res.body.getReader();
    const decoder = new TextDecoder();

    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      const text = decoder.decode(value, { stream: true });
      process.stdout.write(text);
    }
  } catch (err: any) {
    console.error(`[oracld] Stream disconnected: ${err.message}`);
    process.exit(1);
  }
}

async function handleAsk(args: string[]) {
  const question = args.join(" ").trim();
  if (!question) {
    console.error("Error: question required. Usage: oracld ask \"Will X happen?\"");
    process.exit(1);
  }

  console.log(`[oracld] Consulting oracle on: "${question}" ...\n`);
  try {
    // Try daemon first
    const res = await fetch(`${ORACLE_URL}/ask`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
    });

    if (res.ok) {
      const verdict = await res.json();
      printVerdict(verdict);
      return;
    }
  } catch {
    // Daemon unreachable, fallback to direct runAsk
  }

  const verdict = await runAsk(question);
  printVerdict(verdict);
}

function printVerdict(v: any) {
  console.log(`══════════════════════════════════════════════════════════════════════════════`);
  console.log(`  ORACLE VERDICT: ${v.tier} (id: ${v.verdict_id})`);
  console.log(`══════════════════════════════════════════════════════════════════════════════`);
  console.log(`  Question:    ${v.question}`);
  console.log(`  Probability: ${(v.probability * 100).toFixed(1)}%`);
  console.log(`  Confidence:  ${(v.confidence * 100).toFixed(1)}% (CI: ${(v.confidence_interval.lower * 100).toFixed(1)}% - ${(v.confidence_interval.upper * 100).toFixed(1)}%)`);
  console.log(`  Judges:      ${v.judges_valid}/${v.judges_consulted} valid (Latency: ${v.latency_s.toFixed(2)}s)`);
  console.log(`  Disagreement: spread=${v.disagreement.spread.toFixed(3)}, divergence=${v.disagreement.stance_divergence.toFixed(3)}`);
  console.log(`──────────────────────────────────────────────────────────────────────────────`);
  if (v.contributions && v.contributions.length > 0) {
    console.log(`  Judge Contributions:`);
    for (const c of v.contributions) {
      console.log(`    • ${c.judge}: posterior=${(c.posterior * 100).toFixed(1)}% weight=${c.weight.toFixed(2)}`);
    }
  }
