}

async function main() {
  const args = process.argv.slice(2);
  const cmd = args[0];

  if (!cmd || cmd === "--help" || cmd === "-h") {
    printHelp();
    return;
  }

  switch (cmd) {
    case "health":
      await handleHealth();
      break;
    case "live":
    case "stream":
      await handleLive();
      break;
    case "ask":
      await handleAsk(args.slice(1));
      break;
    case "serve":
      const portIdx = args.indexOf("--port");
      const port = portIdx >= 0 && args[portIdx + 1] ? Number(args[portIdx + 1]) : undefined;
      startDaemon(port);
      break;
    default:
      console.error(`Unknown command: ${cmd}`);
      printHelp();
      process.exit(1);
  }
}

main().catch((err) => {
  console.error(`[oracld] Fatal: ${err.message}`);
  process.exit(1);
});

