	Activity() ActivityRepository

	// Cache returns the repository for cached key/blob records.
	Cache() CacheRepository

	// IsInMemory reports whether the backing database is not persisted to
	// disk. In-memory stores are bounded by pruning rather than by disk.
	IsInMemory() bool

	// Close releases the backing database. It is safe to call more than once.
	Close() error
}

// ActivityRepository persists and queries activity log entries.
type ActivityRepository interface {
	// Insert stores an entry and returns it with its assigned ID. A zero
	// Timestamp is replaced with the current time.
	Insert(ctx context.Context, entry ActivityLogEntry) (ActivityLogEntry, error)

	// List returns one page of entries matching the query, newest first
	// unless the query says otherwise. Page and Limit are normalized with
	// ActivityQuery.WithDefaults before use.
	List(ctx context.Context, query ActivityQuery) (ActivityPage, error)

	// Stats aggregates totals and speed histograms over the matching entries.
	Stats(ctx context.Context, query ActivityStatsQuery) (ActivityStats, error)

	// Prune deletes all but the newest maxRows entries. A maxRows of zero or
	// less is a no-op.
	Prune(ctx context.Context, maxRows int) error
}

package server

import (
	"net/http"
	"regexp"
	"strings"

	"github.com/mostlygeek/llama-swap/internal/config"
	"github.com/mostlygeek/llama-swap/internal/process"
	"github.com/mostlygeek/llama-swap/internal/swaputil"
)

// ComfyUI compatibility endpoint. ComfyUI is a web app rather than an
// OpenAI-compatible server, so it is served through its own passthrough bound
// to the reserved config.ComfyUIModelID model. Routes are registered in
// server.go; the model's compatibility settings are applied while loading
// config.

}

// comfyUIIgnorePaths are the paths under /comfyui/ that may not start an
// unloaded model. An open ComfyUI tab retries them on its own, so letting them
// swap the model in would undo every unload while a browser is pointed at it.
//
// This is the built-in equivalent of the upstream.ignorePaths a second ComfyUI
// instance needs when it is served through /upstream/<model>/ instead, so the
// two lists are kept the same: the shared static-asset default, the frontend
// websocket, and its job polling.
var comfyUIIgnorePaths = append(
	config.DefaultUpstreamIgnorePaths(),
	regexp.MustCompile(`^/ws(/|$)`),
	regexp.MustCompile(`^/api/jobs$`),
)

// comfyUIIgnoresPath reports whether path is one that may not start the model.
// path is the decoded path only, so query parameters such as ?clientId= never
// affect the match.
func comfyUIIgnoresPath(path string) bool {
	for _, re := range comfyUIIgnorePaths {
		if re.MatchString(path) {
			return true
		}
	}
	return false
}

// handleComfyUI proxies requests under /comfyui/ to the fixed local
// ComfyUI model. Its compatibility settings are applied while loading config.
func (s *Server) handleComfyUI(w http.ResponseWriter, r *http.Request) {
	if _, ok := s.cfg.Models[config.ComfyUIModelID]; !ok || !s.local.Handles(config.ComfyUIModelID) {
		swaputil.SendResponse(w, r, http.StatusNotFound, "local model "+config.ComfyUIModelID+" not found")
		return
	}

	// Strip the /comfyui prefix before forwarding. URL.Path and PathValue are
	// decoded, so retain the matching escaped suffix in RawPath exactly as the
	// generic /upstream handler does.
	remainingPath := "/" + strings.TrimPrefix(r.PathValue("comfyPath"), "/")
	escapedRemaining := swaputil.EscapedPathSuffix(r.URL.EscapedPath(), "/comfyui")
	r.URL.Path = remainingPath
	r.URL.RawPath = escapedRemaining

	// Only a GET is ignored. A write is a deliberate action even on an ignored
	// path, so queueing a job still starts the model.
	if r.Method == http.MethodGet && comfyUIIgnoresPath(remainingPath) {
		state, ok := s.local.RunningModels()[config.ComfyUIModelID]
		if !ok || state != process.StateReady {
			swaputil.SendResponse(w, r, http.StatusConflict,
				"model "+config.ComfyUIModelID+" is not loaded; ignored ComfyUI paths cannot start it")
			return
		}
	}

	*r = *r.WithContext(swaputil.SetContext(r.Context(), swaputil.ReqContextData{
		ApiKey:   swaputil.ExtractAPIKey(r),
		Model:    config.ComfyUIModelID,
		ModelID:  config.ComfyUIModelID,
		Metadata: make(map[string]string),
	}))
	s.local.ServeHTTP(w, r)
}

package config

import (
	"fmt"
	"net/url"
	"strings"

	"github.com/mostlygeek/llama-swap/internal/tailcat"
)

const TailcatEphemeralKey = "ephemeral"

// TailcatConfig configures the private Tailcat listener and its HTTP policy.
// The listener identity comes from the startup-only -listen-tailcat flag.
type TailcatConfig struct {
	Allow  []string `yaml:"allow"`
	Models []string `yaml:"models"`
	Admin  bool     `yaml:"admin"`
	Debug  bool     `yaml:"debug"`

	AllowedClients []string `yaml:"-"`
}

func validatePeerTailcat(peer *rawPeerConfig) error {
	u, err := url.Parse(peer.Proxy)
	if err != nil {
		return fmt.Errorf("invalid peer proxy URL (%s): %w", peer.Proxy, err)
	}
	isTailcat := strings.EqualFold(u.Scheme, "tailcat")
	if !isTailcat {
		if peer.TailcatKey != "" {
			return fmt.Errorf("tailcatKey is only valid with a tailcat:// proxy")
		}
		return nil
	}

	if !strings.EqualFold(u.Scheme, "tailcat") || u.Opaque != "" || u.User != nil || u.Host == "" ||
		u.Path != "" || u.RawPath != "" || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" {
		return fmt.Errorf("invalid Tailcat peer proxy URL %q: expected tailcat://<connection-token> with no credentials, path, query, fragment, or port", peer.Proxy)
	}
	// Connection blobs use base64url and therefore never contain a colon. This
	// catches explicit ports without passing the case-sensitive token through
	// URL hostname normalization.
	if strings.Contains(u.Host, ":") {
		return fmt.Errorf("invalid Tailcat peer proxy URL %q: explicit ports are not allowed (Tailcat uses port 80)", peer.Proxy)
	}
	blob := u.Host
	if err := tailcat.ValidateConnectionBlob(blob); err != nil {
		return fmt.Errorf("invalid Tailcat connection token: %w", err)
	}
	peer.tailcatBlob = blob
	peer.ProxyURL = &url.URL{Scheme: "http", Host: "server.tailcat"}

	if peer.TailcatKey != "" && peer.TailcatKey != TailcatEphemeralKey {
		loaded, err := tailcat.LoadPrivateKey(peer.TailcatKey, false)
		if err != nil {
			return fmt.Errorf("tailcatKey: %w", err)
		}
		peer.tailcatPrivateKey = loaded
	}
	return nil
}

func validateTailcatConfig(cfg *Config) error {
	if tc := cfg.Tailcat; tc != nil {
		seenAllow := make(map[string]struct{}, len(tc.Allow))
		allowedClients := make([]string, 0, len(tc.Allow))
		for i, raw := range tc.Allow {
			canonical, err := tailcat.ValidateNodePublic(raw)
			if err != nil {
				return fmt.Errorf("tailcat.allow[%d]: invalid node public key: %w", i, err)
			}
			if canonical != raw {
				return fmt.Errorf("tailcat.allow[%d]: must be a full canonical nodekey: public key", i)
			}
			if _, exists := seenAllow[canonical]; exists {
				continue
			}
			seenAllow[canonical] = struct{}{}
			allowedClients = append(allowedClients, canonical)
		}
		tc.Allow = allowedClients
		tc.AllowedClients = allowedClients

		validModels := publicTailcatModelIDs(*cfg)
		seenModels := make(map[string]struct{}, len(tc.Models))
		models := make([]string, 0, len(tc.Models))
		for i, model := range tc.Models {
			if model == "" {
				return fmt.Errorf("tailcat.models[%d]: model ID cannot be empty", i)
			}
			if model != "*" {
				if _, ok := validModels[model]; !ok {
					return fmt.Errorf("tailcat.models[%d]: unknown public model ID %q", i, model)
				}
			}
			if _, exists := seenModels[model]; exists {
				continue
			}
			seenModels[model] = struct{}{}
			models = append(models, model)
		}
		tc.Models = models
	}

	// One stable client identity may safely share transports to the same
	// destination, but using it for different Tailcat servers creates an
	// ambiguous network identity and is rejected up front.
	type destination struct{ server string }
	used := map[string]destination{}
	for peerID, peer := range cfg.Peers {
		clientKey, blob, pk, found := peer.Tailcat()
		if !found || clientKey == "" || clientKey == TailcatEphemeralKey {
			continue
		}
		client := pk.Identity()
		server, _ := tailcat.ConnectionDestination(blob)
		if prev, ok := used[client]; ok && prev.server != server {
			return fmt.Errorf("peers.%s.tailcatKey reuses client node key %s for a different Tailcat destination", peerID, client)
		}
		used[client] = destination{server: server}
	}
	return nil
}

func publicTailcatModelIDs(cfg Config) map[string]struct{} {
	ids := make(map[string]struct{})
	for id, model := range cfg.Models {
		ids[id] = struct{}{}
		for _, alias := range model.Aliases {
			ids[alias] = struct{}{}
		}
	}
	for id := range cfg.Selectors {
		ids[id] = struct{}{}
	}
	for _, profile := range cfg.Profiles {
		for pin := range profile.Pins {
			ids[pin] = struct{}{}
		}
	}
	for peerID, peer := range cfg.Peers {
		for _, model := range peer.Models {
			ids[PeerModelFQN(peerID, model)] = struct{}{}
		}
	}
	return ids
}

