232:func parseActivityQuery(r *http.Request) (store.ActivityQuery, error) {
233:	const defaultLimit = 25
234:	query := store.ActivityQuery{
235:		Limit: defaultLimit,
236:		Page:  1,
237:	}
238:
239:	// model repeats to filter on several models at once (?model=a&model=b).
240:	// A single ?model=x stays a plain exact match.
241:	for _, raw := range r.URL.Query()["model"] {
242:		if model := strings.TrimSpace(raw); model != "" {
243:			query.Models = append(query.Models, model)
244:		}
245:	}
246:
247:	start, err := parseActivityTime(r, "start")
248:	if err != nil {
249:		return store.ActivityQuery{}, err
250:	}
251:	end, err := parseActivityTime(r, "end")
252:	if err != nil {
253:		return store.ActivityQuery{}, err
254:	}
255:	if !start.IsZero() && !end.IsZero() && start.After(end) {
256:		return store.ActivityQuery{}, fmt.Errorf("start must be before end")
257:	}
258:	query.Start, query.End = start, end
259:
260:	minID, err := parseActivityID(r, "min_id")
261:	if err != nil {
262:		return store.ActivityQuery{}, err
263:	}
264:	maxID, err := parseActivityID(r, "max_id")
265:	if err != nil {
266:		return store.ActivityQuery{}, err
267:	}
268:	if minID > 0 && maxID > 0 && minID > maxID {
269:		return store.ActivityQuery{}, fmt.Errorf("min_id must be <= max_id")
270:	}
271:	query.MinID, query.MaxID = minID, maxID
272:
273:	if raw := strings.TrimSpace(r.URL.Query().Get("limit")); raw != "" {
274:		limit, err := parseActivityLimit(raw)
275:		if err != nil {
276:			return store.ActivityQuery{}, err
277:		}
278:		query.Limit = limit
279:	}
280:
281:	if raw := strings.TrimSpace(r.URL.Query().Get("page")); raw != "" {
282:		page, err := strconv.Atoi(raw)
283:		if err != nil || page < 1 {
284:			return store.ActivityQuery{}, fmt.Errorf("page must be >= 1")
285:		}
286:		query.Page = page
287:	}
288:
289:	if raw := strings.TrimSpace(r.URL.Query().Get("sort")); raw != "" {
290:		if _, ok := store.ActivitySortColumn(raw); !ok {
291:			return store.ActivityQuery{}, fmt.Errorf("invalid sort column")
292:		}
293:		query.Sort = raw
294:	}
295:
296:	if raw := strings.TrimSpace(r.URL.Query().Get("order")); raw != "" {
297:		switch strings.ToLower(raw) {
298:		case "asc", "desc":
299:			query.Order = strings.ToLower(raw)
300:		default:
301:			return store.ActivityQuery{}, fmt.Errorf("order must be asc or desc")
302:		}
303:	}
304:
305:	return query, nil
306:}
