332:		sysStats = filteredSys
333:
334:		filteredGpu := make([]perf.GpuStat, 0, len(gpuStats))
335:		for _, g := range gpuStats {
336:			if g.Timestamp.After(after) {
337:				filteredGpu = append(filteredGpu, g)
338:			}
339:		}
340:		gpuStats = filteredGpu
341:	}
342:
343:	w.Header().Set("Content-Type", "application/json")
344:	json.NewEncoder(w).Encode(map[string]any{
345:		"enabled":   true,
