420:// sendDropReportInterval is how often handleAPIEvents reports messages that
421:// were dropped because the send buffer was full.
422:const sendDropReportInterval = 5 * time.Second
423:
424:type messageEnvelope struct {
425:	Type messageType `json:"type"`
426:	Data string      `json:"data"`
427:}
428:
429:// handleAPIEvents streams server events (model status, log data, metrics,
430:// in-flight counts) to the client as Server-Sent Events.
431:func (s *Server) handleAPIEvents(w http.ResponseWriter, r *http.Request) {
432:	w.Header().Set("Content-Type", "text/event-stream")
433:	w.Header().Set("Cache-Control", "no-cache")
434:	w.Header().Set("Connection", "keep-alive")
435:	w.Header().Set("X-Content-Type-Options", "nosniff")
436:	// prevent nginx from buffering SSE
437:	w.Header().Set("X-Accel-Buffering", "no")
438:
439:	flusher, ok := w.(http.Flusher)
440:	if !ok {
441:		swaputil.SendResponse(w, r, http.StatusInternalServerError, "streaming unsupported")
442:		return
443:	}
444:
445:	// internal/event already has a 50K event buffer
446:	// a 1K message buffer should be enough, watch the logs for the warning that the sendBuffer is full
447:	sendBuffer := make(chan messageEnvelope, 1024)
448:	ctx, cancel := context.WithCancel(r.Context())
449:	defer cancel()
450:
451:	// Dropped messages are counted and reported at most once per interval.
452:	// Logging every drop floods the logs because each warning becomes a log
453:	// event that is sent over this same buffer, which drops again.
454:	dropped := newSuppressionCounter(sendDropReportInterval)
455:	cancelled := newSuppressionCounter(sendDropReportInterval)
456:	reportDropped := func(n int) {
457:		s.proxylog.Warnf("handleAPIEvents sendBuffer full, %d messages suppressed", n)
458:	}
459:	reportCancelled := func(n int) {
460:		s.proxylog.Warnf("handleAPIEvents send suppressed due to context done, %d messages suppressed", n)
461:	}
462:	// runs after the event handlers below are unsubscribed so any remaining
463:	// counts are reported before the connection goes away
464:	defer func() {
465:		if n, ok := dropped.Flush(); ok {
466:			reportDropped(n)
467:		}
468:		if n, ok := cancelled.Flush(); ok {
469:			reportCancelled(n)
470:		}
471:	}()
472:
473:	send := func(msg messageEnvelope) {
474:		select {
475:		case sendBuffer <- msg:
476:		case <-ctx.Done():
477:			if n, ok := cancelled.Add(); ok {
478:				reportCancelled(n)
479:			}
480:		default:
481:			if n, ok := dropped.Add(); ok {
482:				reportDropped(n)
483:			}
484:		}
485:	}
486:	sendModels := func() {
487:		if data, err := json.Marshal(s.modelStatus()); err == nil {
488:			send(messageEnvelope{Type: msgTypeModelStatus, Data: string(data)})
489:		}
490:	}
491:	sendLogData := func(source string, data []byte) {
492:		if j, err := json.Marshal(map[string]string{"source": source, "data": string(data)}); err == nil {
493:			send(messageEnvelope{Type: msgTypeLogData, Data: string(j)})
494:		}
495:	}
496:	sendActivity := func(id int) {
497:		if j, err := json.Marshal(map[string]int{"id": id}); err == nil {
498:			send(messageEnvelope{Type: msgTypeActivity, Data: string(j)})
499:		}
500:	}
501:	sendInFlight := func(update swaputil.InFlightRequestsEvent) {
502:		if update.Operation == inflightOperationSnapshot && update.Requests == nil {
503:			update.Requests = []swaputil.InflightRequestEntry{}
504:		}
505:		if j, err := json.Marshal(update); err == nil {
506:			send(messageEnvelope{Type: msgTypeInFlight, Data: string(j)})
507:		}
508:	}
509:	sendUIConfig := func() {
510:		if j, err := json.Marshal(s.cfg.UI); err == nil {
511:			send(messageEnvelope{Type: msgTypeUIConfig, Data: string(j)})
512:		}
513:	}
514:	sendProfile := func() {
515:		if j, err := json.Marshal(map[string]any{"active": nullableProfile(s.ActiveProfile())}); err == nil {
516:			send(messageEnvelope{Type: msgTypeProfile, Data: string(j)})
517:		}
518:	}
519:
520:	defer event.On(func(e swaputil.ProcessStateChangeEvent) { sendModels() })()
521:	defer event.On(func(e swaputil.ConfigFileChangedEvent) { sendModels() })()
522:	defer event.On(func(e swaputil.ProfileChangedEvent) {
523:		sendProfile()
524:		sendModels()
525:	})()
526:	defer s.proxylog.OnLogData(func(data []byte) { sendLogData("proxy", data) })()
527:	defer s.upstreamlog.OnLogData(func(data []byte) { sendLogData("upstream", data) })()
528:	defer event.On(func(e ActivityLogEvent) { sendActivity(e.Metrics.ID) })()
529:	defer event.On(func(e swaputil.InFlightRequestsEvent) { sendInFlight(e) })()
530:
531:	// initial payload
532:	sendLogData("proxy", s.proxylog.GetHistory())
533:	sendLogData("upstream", s.upstreamlog.GetHistory())
534:	sendModels()
535:	sendUIConfig()
536:	sendProfile()
537:	sendInFlight(s.inflight.Current())
538:
539:	for {
540:		select {
541:		case <-r.Context().Done():
542:			return
543:		case <-s.shutdownCtx.Done():
544:			return
545:		case msg := <-sendBuffer:
546:			data, err := json.Marshal(msg)
547:			if err != nil {
548:				continue
549:			}
550:			fmt.Fprintf(w, "event:message\ndata:%s\n\n", data)
551:			flusher.Flush()
552:		}
553:	}
554:}

