339:func (s *Store) PruneActivity(ctx context.Context, maxRows int) error {
340:	if maxRows <= 0 {
341:		return nil
342:	}
343:	// AUTOINCREMENT ids are monotonic and never reused, so the rows beyond
344:	// the newest maxRows are exactly those with id <= MAX(id) - maxRows.
345:	// One statement keeps the per-insert prune cheap; if ids ever become
346:	// sparse this retains fewer than maxRows rows, which is fine for a
347:	// bounded recent-activity cap.
348:	if _, err := s.db.ExecContext(ctx,
349:		`DELETE FROM activity WHERE id <= (SELECT MAX(id) FROM activity) - ?`, maxRows,
350:	); err != nil {
351:		return fmt.Errorf("prune activity: %w", err)
352:	}
353:	return nil
354:}
