366:// activityOrderBy builds a safe ORDER BY clause from the query's sort key and
367:// direction. Unknown sort keys fall back to "id". A secondary "id" sort keeps
368:// pagination stable when the primary column has duplicate values.
369:func activityOrderBy(query ActivityQuery) string {
370:	column, ok := activitySortColumns[query.Sort]
371:	if !ok {
372:		column = "id"
373:	}
374:	direction := "DESC"
375:	if strings.EqualFold(query.Order, "asc") {
376:		direction = "ASC"
377:	}
378:	if column == "id" {
379:		return " ORDER BY id " + direction
380:	}
381:	return " ORDER BY " + column + " " + direction + ", id " + direction
382:}
