391:func calculateHistogramData(values []float64) *HistogramData {
392:	if len(values) == 0 {
393:		return nil
394:	}
395:
396:	sorted := append([]float64(nil), values...)
397:	sort.Float64s(sorted)
398:	minVal := sorted[0]
399:	maxVal := sorted[len(sorted)-1]
400:
401:	p50 := percentile(sorted, 50)
402:	p95 := percentile(sorted, 95)
403:	p99 := percentile(sorted, 99)
404:
405:	if minVal == maxVal {
406:		return &HistogramData{
407:			Bins:    []int{len(values)},
408:			Min:     minVal,
409:			Max:     maxVal,
410:			BinSize: 0,
411:			P50:     p50,
412:			P95:     p95,
413:			P99:     p99,
414:		}
415:	}
416:
417:	const minBins = 5
418:	const maxBins = 20
419:	sturges := int(math.Ceil(math.Log2(float64(len(values))))) + 1
420:	binCount := min(maxBins, max(minBins, sturges))
421:	binSize := (maxVal - minVal) / float64(binCount)
422:
423:	bins := make([]int, binCount)
424:	for _, value := range values {
425:		idx := min(int(math.Floor((value-minVal)/binSize)), binCount-1)
426:		bins[idx]++
427:	}
428:
429:	return &HistogramData{
430:		Bins:    bins,
431:		Min:     minVal,
432:		Max:     maxVal,
433:		BinSize: binSize,
434:		P50:     p50,
435:		P95:     p95,
436:		P99:     p99,
437:	}
438:}
439:
440:func percentile(sorted []float64, p float64) float64 {
441:	if len(sorted) == 0 {
442:		return 0
443:	}
444:	if len(sorted) == 1 {
445:		return sorted[0]
446:	}
447:	rank := (p / 100) * float64(len(sorted)-1)
448:	lower := int(math.Floor(rank))
449:	upper := int(math.Ceil(rank))
450:	fraction := rank - float64(lower)
451:	return sorted[lower] + fraction*(sorted[upper]-sorted[lower])
452:}
