454:// activityWhere builds a parameterized WHERE clause from a filter. It returns
455:// an empty string when nothing is filtered. Callers append further conditions
456:// with " AND ...", so the clause is always a single unparenthesized conjunction.
457:func activityWhere(filter ActivityFilter) (string, []any) {
458:	var conditions []string
459:	var args []any
460:
461:	models := make([]string, 0, len(filter.Models))
462:	for _, model := range filter.Models {
463:		if model = strings.TrimSpace(model); model != "" {
464:			models = append(models, model)
465:		}
466:	}
467:	if len(models) > 0 {
468:		placeholders := strings.TrimSuffix(strings.Repeat("?, ", len(models)), ", ")
469:		conditions = append(conditions, "model_id IN ("+placeholders+")")
470:		for _, model := range models {
471:			args = append(args, model)
472:		}
473:	}
474:
475:	if !filter.Start.IsZero() {
476:		conditions = append(conditions, "ts_created >= ?")
477:		args = append(args, filter.Start.Unix())
478:	}
479:	if !filter.End.IsZero() {
480:		conditions = append(conditions, "ts_created <= ?")
481:		args = append(args, filter.End.Unix())
482:	}
483:	if filter.MinID > 0 {
484:		conditions = append(conditions, "id >= ?")
485:		args = append(args, filter.MinID)
486:	}
487:	if filter.MaxID > 0 {
488:		conditions = append(conditions, "id <= ?")
489:		args = append(args, filter.MaxID)
490:	}
491:
492:	if len(conditions) == 0 {
493:		return "", nil
494:	}
495:	return " WHERE " + strings.Join(conditions, " AND "), args
496:}
