312:// failedErrorMessage builds a human-readable description for a non-200 response.
313:// It prefers an error message parsed from the (decompressed) body and falls back
314:// to the HTTP status text. A non-nil decErr indicates the body could not be
315:// decoded, in which case the decode error is described instead.
316:func failedErrorMessage(status int, body []byte, decErr error) string {
317:	const maxLen = 500
318:	if decErr != nil {
319:		return fmt.Sprintf("response decode failed: %v", decErr)
320:	}
321:	if msg := extractErrorMessage(body); msg != "" {
322:		if len(msg) > maxLen {
323:			msg = msg[:maxLen] + "..."
324:		}
325:		return msg
326:	}
327:	if text := http.StatusText(status); text != "" {
328:		return fmt.Sprintf("%d %s", status, text)
329:	}
330:	return fmt.Sprintf("HTTP %d", status)
