373:func processStreamingResponse(modelID string, start time.Time, body []byte) (ActivityLogEntry, error) {
374:	var (
375:		inputTokens, outputTokens int64
376:		cachedTokens              int64 = -1
377:		hasAny                    bool
378:		timings                   gjson.Result
379:		responseMetrics           gjson.Result
380:	)
381:
382:	prefix := []byte("data:")
383:	for offset := 0; offset < len(body); {
384:		nl := bytes.IndexByte(body[offset:], '\n')
385:		var line []byte
386:		if nl == -1 {
387:			line = body[offset:]
388:			offset = len(body)
389:		} else {
390:			line = body[offset : offset+nl]
391:			offset += nl + 1
392:		}
393:
394:		line = bytes.TrimSpace(line)
395:		if len(line) == 0 || !bytes.HasPrefix(line, prefix) {
396:			continue
397:		}
398:		data := bytes.TrimSpace(line[len(prefix):])
399:		if len(data) == 0 || bytes.Equal(data, []byte("[DONE]")) {
400:			continue
401:		}
402:		if !gjson.ValidBytes(data) {
403:			continue
404:		}
405:		parsed := gjson.ParseBytes(data)
406:
407:		for _, path := range usagePaths {
408:			u := parsed.Get(path)
409:			if !u.Exists() {
410:				continue
411:			}
412:			i, o, c, ok := extractUsageTokens(u)
413:			if !ok {
414:				continue
415:			}
416:			hasAny = true
417:			if i > 0 {
418:				inputTokens = i
419:			}
420:			if o > 0 {
421:				outputTokens = o
422:			}
423:			if c >= 0 {
424:				cachedTokens = c
425:			}
426:		}
427:		if t := parsed.Get("timings"); t.Exists() {
428:			timings = t
429:			hasAny = true
430:		}
431:		if m := parsed.Get("metrics"); m.Exists() {
432:			responseMetrics = m
433:			hasAny = true
434:		}
435:	}
436:
437:	if !hasAny {
438:		return ActivityLogEntry{}, fmt.Errorf("no valid JSON data found in stream")
439:	}
440:
441:	return buildMetrics(modelID, start, inputTokens, outputTokens, cachedTokens, timings, responseMetrics), nil
442:}
