444:func parseMetrics(modelID string, start time.Time, usage, timings, responseMetrics gjson.Result) (ActivityLogEntry, error) {
445:	input, output, cached, _ := extractUsageTokens(usage)
446:	return buildMetrics(modelID, start, input, output, cached, timings, responseMetrics), nil
447:}
