449:// buildMetrics composes an ActivityLogEntry from accumulated token counts and
450:// optional llama-server timings (which override input/output and provide rates)
451:// or vLLM response metrics (rates and speculative decoding counters).
452:func buildMetrics(modelID string, start time.Time, inputTokens, outputTokens, cachedTokens int64, timings, responseMetrics gjson.Result) ActivityLogEntry {
453:	wallDurationMs := int(time.Since(start).Milliseconds())
454:	durationMs := wallDurationMs
455:	tokensPerSecond := -1.0
456:	promptPerSecond := -1.0
457:	draftTokens := -1
458:	draftAccTokens := -1
459:
460:	if timings.Exists() {
461:		inputTokens = timings.Get("prompt_n").Int()
462:		outputTokens = timings.Get("predicted_n").Int()
463:		promptPerSecond = timings.Get("prompt_per_second").Float()
464:		tokensPerSecond = timings.Get("predicted_per_second").Float()
465:		timingsDurationMs := int(timings.Get("prompt_ms").Float() + timings.Get("predicted_ms").Float())
466:		if timingsDurationMs > durationMs {
467:			durationMs = timingsDurationMs
468:		}
469:		if cachedValue := timings.Get("cache_n"); cachedValue.Exists() {
470:			cachedTokens = cachedValue.Int()
471:		}
472:		if timings.Get("draft_n").Exists() && timings.Get("draft_n_accepted").Exists() {
473:			draftTokens = int(timings.Get("draft_n").Int())
474:			draftAccTokens = int(timings.Get("draft_n_accepted").Int())
475:		}
476:	}
477:	// vLLM reports speculative decoding counts under metrics.speculative_decoding
478:	// when started with --per-request-spec-decode-metrics (#1032). Both counters
479:	// are required so the acceptance rate is never derived from a half-filled
480:	// object.
481:	if spec := responseMetrics.Get("speculative_decoding"); spec.Exists() {
482:		drafted := spec.Get("num_draft_tokens")
483:		accepted := spec.Get("num_accepted_draft_tokens")
484:		if drafted.Exists() && accepted.Exists() {
485:			draftTokens = int(drafted.Int())
486:			draftAccTokens = int(accepted.Int())
487:		}
488:	}
489:	if timeToFirstToken := responseMetrics.Get("time_to_first_token_ms"); timeToFirstToken.Exists() && timeToFirstToken.Float() > 0 {
490:		cachedForRate := cachedTokens
491:		if cachedForRate < 0 {
492:			cachedForRate = 0
493:		}
494:		promptPerSecond = float64(inputTokens-cachedForRate) / (timeToFirstToken.Float() / 1000)
495:	}
496:	if meanInterTokenLatency := responseMetrics.Get("mean_itl_ms"); meanInterTokenLatency.Exists() && meanInterTokenLatency.Float() > 0 {
497:		tokensPerSecond = 1000 / meanInterTokenLatency.Float()
498:	}
499:
500:	return ActivityLogEntry{
501:		Timestamp: time.Now(),
502:		Model:     modelID,
503:		Tokens: TokenMetrics{
504:			CachedTokens:    int(cachedTokens),
505:			DraftTokens:     draftTokens,
506:			DraftAccTokens:  draftAccTokens,
507:			InputTokens:     int(inputTokens),
508:			OutputTokens:    int(outputTokens),
509:			PromptPerSecond: promptPerSecond,
510:			TokensPerSecond: tokensPerSecond,
511:		},
512:		DurationMs: durationMs,
513:	}
514:}
