516:// decompressBody decompresses the body based on the Content-Encoding header.
517:func decompressBody(body []byte, encoding string) ([]byte, error) {
518:	switch strings.ToLower(strings.TrimSpace(encoding)) {
519:	case "gzip":
520:		reader, err := gzip.NewReader(bytes.NewReader(body))
521:		if err != nil {
522:			return nil, err
523:		}
524:		defer reader.Close()
525:		return io.ReadAll(reader)
526:	case "deflate":
527:		reader := flate.NewReader(bytes.NewReader(body))
528:		defer reader.Close()
529:		return io.ReadAll(reader)
530:	default:
531:		return body, nil
532:	}
533:}
