535:// filterAcceptEncoding filters Accept-Encoding to only gzip/deflate so response
536:// bodies remain decompressible for metrics parsing.
537:func filterAcceptEncoding(acceptEncoding string) string {
538:	if acceptEncoding == "" {
539:		return ""
540:	}
541:
542:	supported := map[string]bool{"gzip": true, "deflate": true}
543:	var filtered []string
544:	for part := range strings.SplitSeq(acceptEncoding, ",") {
545:		encoding, _, _ := strings.Cut(strings.TrimSpace(part), ";")
546:		if supported[strings.ToLower(encoding)] {
547:			filtered = append(filtered, strings.TrimSpace(part))
548:		}
549:	}
550:	return strings.Join(filtered, ", ")
551:}
