553:// responseBodyCopier tees the upstream response to the client while buffering
554:// it for metrics parsing. Status defaults to 200 until WriteHeader is called.
555:type responseBodyCopier struct {
556:	http.ResponseWriter
557:	body        *bytes.Buffer
558:	tee         io.Writer
559:	status      int
560:	wroteHeader bool
561:	start       time.Time
562:}
563:
564:func newBodyCopier(w http.ResponseWriter) *responseBodyCopier {
565:	buf := &bytes.Buffer{}
566:	return &responseBodyCopier{
567:		ResponseWriter: w,
568:		body:           buf,
569:		tee:            io.MultiWriter(w, buf),
570:		status:         http.StatusOK,
571:		start:          time.Now(),
572:	}
573:}
574:
575:func (w *responseBodyCopier) Write(b []byte) (int, error) {
576:	if !w.wroteHeader {
577:		w.WriteHeader(http.StatusOK)
578:	}
579:	// On a protocol upgrade (e.g. websocket) the body is raw framed data, not a
580:	// metrics-parseable response, so write straight to the client without
581:	// buffering a copy we can't use.
582:	if w.status == http.StatusSwitchingProtocols {
583:		return w.ResponseWriter.Write(b)
584:	}
585:	return w.tee.Write(b)
586:}
587:
588:func (w *responseBodyCopier) WriteHeader(statusCode int) {
589:	if w.wroteHeader {
590:		return
591:	}
592:	w.wroteHeader = true
593:	w.status = statusCode
594:	w.ResponseWriter.WriteHeader(statusCode)
595:}
