606:// WroteHeader reports whether a response status reached the client.
607:func (w *responseBodyCopier) WroteHeader() bool { return w.wroteHeader }
608:
609:// Flush forwards to the underlying writer so streaming responses still flush.
610:func (w *responseBodyCopier) Flush() {
611:	f, ok := w.ResponseWriter.(http.Flusher)
612:	if !ok {
613:		return
614:	}
615:	// Flushing commits the implicit 200, so the response has started even if
616:	// nothing wrote a header. Recorded here for the same reason as in
617:	// statusRecorder: the client-closed sentinel must not overwrite it.
618:	if !w.wroteHeader {
619:		w.WriteHeader(http.StatusOK)
620:	}
621:	f.Flush()
622:}
