// stubRouter is a minimal router.LocalRouter for Server dispatch tests.
type stubRouter struct {
	models        map[string]bool
	response      string
	serveHTTP     func(http.ResponseWriter, *http.Request)
	shutdownCalls atomic.Int32
	// runningMu guards running: watchModelState reads it via RunningModels()
	// while tests mutate it. The real baseRouter returns a snapshot; the
	// stub mirrors that contract with a locked copy.
	runningMu     sync.Mutex
	running       map[string]process.ProcessState
	unloadCalls   atomic.Int32
	unloadModels  []string
	unloadTimeout time.Duration
	loggers       map[string]*logmon.Monitor
}

func newStubRouter(models []string, response string) *stubRouter {
	m := make(map[string]bool, len(models))
	for _, id := range models {
		m[id] = true
	}
	return &stubRouter{models: m, response: response}
}

func (s *stubRouter) Handles(model string) bool      { return s.models[model] }
func (s *stubRouter) Shutdown(_ time.Duration) error { s.shutdownCalls.Add(1); return nil }
func (s *stubRouter) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if s.serveHTTP != nil {
		s.serveHTTP(w, r)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(s.response))
}

func (s *stubRouter) RunningModels() map[string]process.ProcessState {
	s.runningMu.Lock()
	defer s.runningMu.Unlock()
	m := make(map[string]process.ProcessState, len(s.running))
	for k, v := range s.running {
		m[k] = v
	}
	return m
}

// setRunningState and deleteRunningState mutate the stub running map under
// the same lock RunningModels takes, so concurrent watchModelState polls
// never race test-driven state changes.
func (s *stubRouter) setRunningState(id string, st process.ProcessState) {
	s.runningMu.Lock()
	defer s.runningMu.Unlock()
	if s.running == nil {
		s.running = make(map[string]process.ProcessState)
	}
	s.running[id] = st
}

func (s *stubRouter) deleteRunningState(id string) {
	s.runningMu.Lock()
	defer s.runningMu.Unlock()
	delete(s.running, id)
}
func (s *stubRouter) Unload(timeout time.Duration, models ...string) {
	s.unloadCalls.Add(1)
	s.unloadTimeout = timeout
	s.unloadModels = append([]string(nil), models...)
}
func (s *stubRouter) ProcessLogger(modelID string) (*logmon.Monitor, bool) {
	if s.loggers != nil {
		if lg, ok := s.loggers[modelID]; ok {
			return lg, true
		}
	}
	return nil, false
}

// newTestServer wires a Server with stub routers and a built mux.
func newTestServer(local router.LocalRouter, peer router.Router) *Server {
	ctx, cancel := context.WithCancel(context.Background())
	proxylog := logmon.NewWriter(io.Discard)
	st, err := store.New("")
  st, err := sqlite.New("")
	}
	s := &Server{
		cfg:         config.Config{},
		muxlog:      logmon.NewWriter(io.Discard),
		proxylog:    proxylog,
		upstreamlog: logmon.NewWriter(io.Discard),
		inflight:    newInflightTracker(),
		metrics:     newMetricsMonitor(proxylog, 0, 0, st),
		store:       st,
		local:       local,
