	for _, s := range []string{"", " ", "Bad Header", "Bad@Header", "a/b", "quote\"d", "tab\there"} {
		if IsHTTPToken(s) {
			t.Errorf("IsHTTPToken(%q) = true, want false", s)
		}
	}
}

