93:func (r *activityRepository) List(ctx context.Context, query store.ActivityQuery) (store.ActivityPage, error) {
94:	query = query.WithDefaults()
95:	offset := (query.Page - 1) * query.Limit
96:
97:	where, args := activityWhere(query.ActivityFilter)
98:	var total int
99:	if err := r.db.QueryRowContext(ctx, `SELECT COUNT(*) FROM activity`+where, args...).Scan(&total); err != nil {
100:		return store.ActivityPage{}, fmt.Errorf("count activity: %w", err)
101:	}
102:
103:	rows, err := r.db.QueryContext(ctx, `
104:		SELECT
105:			id, ts_created, src, model_id, req_path, resp_content_type, resp_status_code,
106:			cache_tokens, draft_tokens, draft_acc_tokens, input_tokens, output_tokens,
107:			prompt_per_second, tokens_per_second, duration_ms, error_msg, metadata_json
108:		FROM activity`+where+activityOrderBy(query)+`
109:		LIMIT ? OFFSET ?`,
110:		append(args, query.Limit, offset)...,
111:	)
112:	if err != nil {
113:		return store.ActivityPage{}, fmt.Errorf("list activity: %w", err)
114:	}
115:	defer rows.Close()
116:
117:	entries := []store.ActivityLogEntry{}
118:	for rows.Next() {
119:		entry, err := scanActivity(rows)
120:		if err != nil {
121:			return store.ActivityPage{}, err
122:		}
123:		entries = append(entries, entry)
124:	}
125:	if err := rows.Err(); err != nil {
126:		return store.ActivityPage{}, fmt.Errorf("list activity rows: %w", err)
127:	}
128:
129:	return store.ActivityPage{
130:		Data:       entries,
131:		Page:       query.Page,
132:		Limit:      query.Limit,
133:		Total:      total,
134:		TotalPages: store.TotalPages(total, query.Limit),
135:	}, nil
136:}
