139:	filter := store.ActivityFilter{}
140:	if model := strings.TrimSpace(query.Model); model != "" {
141:		filter.Models = []string{model}
142:	}
143:	where, args := activityWhere(filter)
144:	row := r.db.QueryRowContext(ctx, `
145:		SELECT
146:			COALESCE(MAX(id), 0),
147:			COALESCE(SUM(input_tokens), 0),
148:			COALESCE(SUM(output_tokens), 0),
149:			COALESCE(SUM(CASE WHEN cache_tokens > 0 THEN cache_tokens ELSE 0 END), 0)
150:		FROM activity`+where, args...)
