152:	var stats store.ActivityStats
153:	if err := row.Scan(&stats.TotalRequests, &stats.TotalInputTokens, &stats.TotalOutputTokens, &stats.TotalCacheTokens); err != nil {
154:		return store.ActivityStats{}, fmt.Errorf("activity stats: %w", err)
155:	}
156:
157:	promptValues, genValues, err := r.speedValues(ctx, where, args)
158:	if err != nil {
159:		return store.ActivityStats{}, err
160:	}
161:	stats.PromptHistogram = store.NewHistogram(promptValues)
162:	stats.GenerationHistogram = store.NewHistogram(genValues)
163:	return stats, nil
